  'copilotAdoption.page.theShareLicensedUsersUsedCopilotLeastOnceSelected': 'The share of licensed users who used Copilot at least once in the selected period.',
  'copilotAdoption.page.deliberatelyLowBarWeakestNumberPageOneInteractionDays': 'A deliberately low bar, and the weakest number on this page: one interaction in {v0} days counts the same as fifty. It is here because it is the figure everyone else quotes, so it needs to be visible and comparable - but "habitual users" below is the one to act on.',
  'copilotAdoption.page.active2': '{v0} active / {v1} {v2} = {v3}',
  'copilotAdoption.page.activityComesCopilotAuditLogDayPeriodFallingBack': 'Activity comes from the Copilot audit log for the {v0}-day period, falling back to Microsoft’s per-user usage report where the audit import is unavailable.{v1}',
  'copilotAdoption.page.habitualUsers': 'Habitual users',
  'copilotAdoption.page.haveMadeCopilotPartWorkingWeek': '{v0} have made Copilot part of the working week',
  'copilotAdoption.page.licensedUsersWhomCopilotRoutinePartWorkingWeekSomething': 'Licensed users for whom Copilot is a routine part of the working week, rather than something they have merely touched.',
  'copilotAdoption.page.userHabitualWhenEngagementScoreReachesOutEstablishedChampion': 'A user is habitual when their engagement score reaches {v0} out of 100 - the Established and Champion bands. That score is the weighted blend of frequency, depth per active day and breadth of Copilot surfaces set out on the Method tab.',
  'copilotAdoption.page.usersScoring': '{v0} users scoring >= {v1} / {v2} {v3} = {v4}',
  'copilotAdoption.page.thisFigureTracksRealisedValueAdoptionRateSitWhile': 'This is the figure that tracks realised value. Adoption rate can sit at 100% while this sits near zero, which is exactly the situation a renewal conversation needs to surface.{v0}',
  'copilotAdoption.page.reclaimableLicences2': 'Reclaimable licences',
  'copilotAdoption.page.certainProbableReviewExcluded': '{v0} certain, {v1} probable, {v2} review, {v3} excluded',
  'copilotAdoption.page.licencesSafeEnoughIncludeActionableReclaimTotalDisabledAccounts': 'Licences safe enough to include in the actionable reclaim total. Disabled accounts are certain. Enabled, long-tenured never-used accounts are probable. Dormant, too-new and unknown-tenure accounts are review-only.',
  'copilotAdoption.page.newUserProtectedDaysUsingGraphUserCreateddatetimeAccount': 'A new user is protected for {v0} days using Graph user.createdDateTime as the account-age proxy until true seat-tenure history exists. Active new users have their expected active days prorated; inactive new users are "too new to judge". {v1}',

  'copilotAdoption.page.certainProbableReclaimableReviewOnlyExcludedUsersStillRemain': '{v0} certain + {v1} probable{v2} = {v3} reclaimable. {v4} review-only and {v5} excluded users still remain in the licensed denominator. Reconciles against the band breakdown as {v6} never used + {v7} dormant + {v8} disabled-but-active = {v9} reclaimable{v10} + {v11} held back for review or exclusion.',
  'copilotAdoption.page.reclaimWindowMismatchDeduction': '{count} probable seats held back because Microsoft\'s usage-report period does not match this window',
  'copilotAdoption.page.reclaimWindowMismatchAddBack': '{count} held back for window mismatch',
  'copilotAdoption.page.drillThroughLicensedUsersTabReclaimTierFilterEach': 'Drill through on the Licensed users tab with the Reclaim tier filter; each tier uses the same reclaimEligibility key counted here. Expired exclusions are shown for re-review rather than silently honoured forever.',
  'copilotAdoption.page.disabledSeats': 'Disabled seats',
  'copilotAdoption.page.disabledAccountsStillHoldingCopilotLicence': 'Disabled accounts still holding a Copilot licence',
  'copilotAdoption.page.copilotSeatsAssignedDisabledEntraAccountsRawInventoryActionable': 'Copilot seats assigned to disabled Entra accounts. This is the raw inventory, not the actionable total: any of these that an administrator has excluded from reclaim are still counted here but are not in Reclaimable licences.',
  'copilotAdoption.page.countedLicensedUserRowsAccountenabledFalseIncludingAdminExcluded': 'Counted from licensed-user rows where accountEnabled is false, including admin-excluded ones. Admin exclusions remain visible separately and do not remove the user from the licensed denominator.',
  'copilotAdoption.page.disabledLicensedAccountCertainReclaimsDifferenceAdminExcluded': '{v0} disabled licensed account(s), of which {v1} are certain reclaims; the difference is admin-excluded.',
  'copilotAdoption.page.requiresGraphUserMetadataImportPopulatedAccountenabled': 'Requires the Graph user metadata import to have populated accountEnabled.',
  'copilotAdoption.page.averageEngagement': 'Average engagement',
